#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
# --room と日付を一緒に渡す（Issue #88 の 2 つ目）
u=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t13:00\t14:00\tz\nkaede\t2026-01-02\t09:00\t10:00\ty\n' > "$u"
[ "$(BOOKINGS=$u bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$u bash src/list.sh --room aoi 2026-01-03)" ] || { echo "list --room with a date that has no booking should print nothing"; fail=1; }
# --room に値が無いときは usage で exit 2（cli-conventions.md）
err=$(BOOKINGS=$u bash src/list.sh --room 2>&1 >/dev/null); rc=$?
[ $rc = 2 ] && [ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without a value should exit 2 with usage"; fail=1; }
# --room と不正な日付を一緒に渡したときも exit 2
BOOKINGS=$u bash src/list.sh --room aoi 2026/01/02 >/dev/null 2>&1; [ $? = 2 ] || { echo "list --room with a malformed date should exit 2"; fail=1; }
rm -f "$t" "$u"; exit $fail

