err=$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null); [ $? = 2 ] || { echo "list --room without value should exit 2"; fail=1; }
[ "$err" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value usage: $err"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null)" ] || { echo "list --room without value should print nothing to stdout"; fail=1; }
rm -f "$t"; exit $fail

