BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
room=
if [ "${1:-}" = --room ]; then
  [ $# -ge 2 ] || { echo "usage: list.sh [--room ROOM] [DATE]" >&2; exit 2; }
  room=$2; shift 2
fi
if [ -n "${1:-}" ] && ! [[ "$1" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "bad date: $1 (expected YYYY-MM-DD)" >&2; exit 2; fi
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" -v r="$room" 'NF && (d == "" || $2 == d) && (r == "" || $1 == r) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
# --room with a date: both filters apply (AND)
[ "$(BOOKINGS=$t bash src/list.sh --room kaede 2026-01-01)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list --room ROOM DATE: matching room and date"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/list.sh --room aoi 2026-01-02)" ] || { echo "list --room ROOM DATE: date with no booking in the room should print nothing"; fail=1; }
BOOKINGS=$t bash src/list.sh --room aoi 2026/01/01 >/dev/null 2>&1; [ $? = 2 ] || { echo "list --room ROOM with a malformed date should exit 2"; fail=1; }
# --room without a value: exit 2, usage on stderr, nothing on stdout
out=$(BOOKINGS=$t bash src/list.sh --room 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "list --room without a value should exit 2 (got $rc)"; fail=1; }
[ -z "$out" ] || { echo "list --room without a value should print nothing on stdout"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh --room 2>&1 >/dev/null)" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without a value: usage message"; fail=1; }
rm -f "$t"; exit $fail

